[data-mp-modal] {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
.mp-modal-card {
  position: relative;
  box-sizing: border-box;
  background: #FFFFFF;
  padding: 32px;
  border-radius: 8px;
  width: 600px;
  max-width: calc(100vw - 32px);
  min-height: 200px;
  text-align: center;
}
@media (max-width: 480px) {
  .mp-modal-card {
    padding: 24px 20px;
  }
}
.mp-modal-card .mp-modal-title {
  font-size: 19px;
  font-weight: 600;
  margin: 0 0 8px;
  color: #09528f;
}
.mp-modal-card .mp-modal-subtitle {
  font-size: 14px;
  margin: 0 0 20px;
  color: #09528f;
  opacity: 0.75;
}
.mp-modal-logo {
  max-height: 86px;
  margin-bottom: 16px;
}
.mp-modal-card .mp-lang-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 8px 0;
}
.mp-modal-card .mp-lang-row .mp-lang-toggle {
  flex: 0 0 calc((25% - 6px) * 0.9);
  min-width: 72px;
  margin: 0;
}
.mp-modal-card .mp-lang-toggle {
  display: block;
  box-sizing: border-box;
  width: 90%;
  margin: 8px auto;
  padding: 10px;
  border: 1px solid #0b60a8;
  border-radius: 6px;
  background: #09528f;
  text-decoration: none;
  color: #ebf2f8;
}
.mp-modal-card .mp-lang-toggle:hover {
  background: #ebf2f8;
  color: #09528f;
}
.mp-modal-close-x {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: #6B7280;
  cursor: pointer;
  border-radius: 6px;
}
.mp-modal-close-x:hover {
  background: rgba(0,0,0,0.05);
}

.mp-lang-current {
  font-weight: 700;
  text-decoration: underline;
}
